UPDATE articles SET title_fa='علت روشن شدن چراغ چک موتور و مسیر تشخیص درست', content_fa='<h2>نشانه‌هایی که باید جدی بگیرید</h2><p>چراغ چک همیشه به معنی خرابی یک قطعه مشخص نیست؛ کد خطا باید کنار داده زنده و علائم خودرو تفسیر شود.</p><h2>مسیر بررسی در تعمیرگاه</h2><p>ابتدا شرایط بروز ایراد ثبت می‌شود، سپس اسکن ECU و اندازه‌گیری انجام می‌گیرد تا علت اصلی از نشانه جدا شود.</p><h2>پرسش‌های متداول</h2><h3>آیا تعویض قطعه بدون دیاگ کافی است؟</h3><p>خیر؛ تعویض بدون اندازه‌گیری ممکن است هزینه اضافی ایجاد کند.</p>' WHERE slug='guide-1-check-engine';
UPDATE articles SET title_fa='چرا خودرو صبح‌ها سخت روشن می‌شود؟', content_fa='<h2>علت‌های رایج</h2><p>افت ولتاژ باتری، فشار سوخت، سنسور دما و نشتی هوا از علت‌های مهم سخت روشن شدن هستند.</p><h2>روش تشخیص</h2><p>ولتاژ باتری، فشار سوخت، جرقه و داده زنده ECU باید در زمان بروز ایراد بررسی شوند.</p><h2>راهکار</h2><p>پس از تأیید علت، تعمیر با اولویت ایمنی و جلوگیری از تعویض حدسی قطعات انجام می‌شود.</p>' WHERE slug='guide-2-hard-start';
UPDATE articles SET title_fa='تست سلامت باتری و دینام با اندازه‌گیری افت ولتاژ', content_fa='<h2>بررسی برق خودرو</h2><p>ولتاژ شارژ به‌تنهایی کافی نیست؛ افت ولتاژ کابل‌های مثبت و منفی زیر بار نیز باید اندازه‌گیری شود.</p><h2>نشانه‌های خرابی</h2><p>استارت سنگین، کم‌نور شدن چراغ‌ها و خوابیدن باتری می‌تواند از شارژ نامناسب یا اتصال ضعیف باشد.</p>' WHERE slug='guide-3-battery-alternator';
UPDATE articles SET title_fa='علائم خرابی سنسور اکسیژن و افزایش مصرف سوخت', content_fa='<h2>نشانه‌ها</h2><p>افزایش مصرف سوخت و نوسان اصلاح سوخت می‌تواند با عملکرد سنسور اکسیژن مرتبط باشد.</p><h2>تشخیص</h2><p>داده زنده، اصلاح کوتاه‌مدت و بلندمدت سوخت و سلامت سیم‌کشی باید با هم بررسی شوند.</p>' WHERE slug='guide-4-oxygen-sensor';
UPDATE articles SET title_fa='بد کار کردن موتور در حالت درجا؛ از شمع تا دریچه گاز', content_fa='<h2>علت‌های محتمل</h2><p>جرقه ضعیف، نشتی هوا، کثیفی دریچه گاز و عدم تعادل انژکتورها از علت‌های رایج لرزش درجا هستند.</p><h2>راهکار تعمیر</h2><p>خطای میس‌فایر، تست جرقه و داده‌های موتور پیش از تعویض قطعه بررسی می‌شود.</p>' WHERE slug='guide-5-rough-idle';
UPDATE articles SET title_fa='تفاوت خطای سنسور با خرابی سیم‌کشی خودرو', content_fa='<h2>قبل از تعویض سنسور</h2><p>تغذیه، اتصال بدنه، سیگنال و پیوستگی سیم باید اندازه‌گیری شود؛ کد خطا به‌تنهایی قطعه معیوب را مشخص نمی‌کند.</p><h2>نتیجه</h2><p>عیب‌یابی مرحله‌ای از هزینه تعویض قطعات سالم جلوگیری می‌کند.</p>' WHERE slug='guide-6-sensor-wiring';
UPDATE articles SET title_fa='شبکه CAN چیست و چرا چند چراغ هشدار هم‌زمان روشن می‌شود؟', content_fa='<h2>شبکه ارتباطی خودرو</h2><p>قطع ارتباط یک ماژول یا افت ولتاژ می‌تواند چند سامانه را هم‌زمان از کار بیندازد.</p><h2>تشخیص</h2><p>اسکن همه ماژول‌ها، تست مقاومت شبکه و بررسی شکل موج CAN-H و CAN-L مسیر عیب را مشخص می‌کند.</p>' WHERE slug='guide-7-can-bus';
UPDATE articles SET title_fa='ضربه گیربکس اتوماتیک؛ چه زمانی رانندگی خطرناک است؟', content_fa='<h2>نشانه‌های هشدار</h2><p>ضربه شدید، لغزش و ورود گیربکس به حالت اضطراری نیاز به بررسی فوری دارد.</p><h2>بررسی تخصصی</h2><p>سطح و کیفیت روغن، دما، خطاهای TCM و فشار خط باید بررسی شوند.</p>' WHERE slug='guide-8-automatic-gearbox-shock';
UPDATE articles SET title_fa='تعویض روغن گیربکس اتوماتیک؛ زمان‌بندی و خطاهای رایج', content_fa='<h2>اهمیت روغن صحیح</h2><p>نوع روغن و روش تخلیه باید مطابق مشخصات گیربکس باشد؛ ترکیب روغن نامناسب آسیب‌زاست.</p><h2>سرویس اصولی</h2><p>سطح روغن در دمای مشخص و پس از بررسی نشتی تنظیم می‌شود.</p>' WHERE slug='guide-9-gearbox-fluid';
UPDATE articles SET title_fa='کولر خودرو خنک نمی‌کند؛ کمبود گاز یا ایراد کمپرسور؟', content_fa='<h2>تشخیص سرمایش ضعیف</h2><p>با اندازه‌گیری فشارهای بالا و پایین و تست نشتی می‌توان کمبود گاز را از ایراد کمپرسور جدا کرد.</p><h2>سرویس</h2><p>وکیوم و شارژ باید با مقدار استاندارد انجام شود تا کمپرسور آسیب نبیند.</p>' WHERE slug='guide-10-car-ac';
UPDATE articles SET title_fa='صدای تق‌تق جلوبندی از کدام قطعه است؟', content_fa='<h2>محل و زمان صدا</h2><p>صدای دست‌انداز، ترمز و چرخش فرمان سرنخ تشخیص بوش، سیبک، طبق یا کمک‌فنر است.</p><h2>راهکار</h2><p>قطعات دارای لقی پس از تست مکانیکی و بررسی ایمنی تعویض می‌شوند.</p>' WHERE slug='guide-11-suspension-noise';
UPDATE articles SET title_fa='لرزش فرمان در سرعت بالا و نقش میزان فرمان', content_fa='<h2>بررسی مرحله‌ای</h2><p>بالانس، تاب دیسک، لقی جلوبندی و زوایای چرخ باید جداگانه بررسی شوند.</p><h2>نکته مهم</h2><p>تنظیم فرمان بدون رفع لقی یا بالانس، مشکل را به‌طور کامل حل نمی‌کند.</p>' WHERE slug='guide-12-steering-vibration';
UPDATE articles SET title_fa='لرزش هنگام ترمز گرفتن؛ دیسک یا کالیپر؟', content_fa='<h2>نشانه‌ها</h2><p>لرزش پدال و فرمان می‌تواند از تاب دیسک، گیرکردن کالیپر یا لقی قطعات باشد.</p><h2>تعمیر</h2><p>دیسک، لنت، کالیپر و روغن ترمز باید هم‌زمان بازدید شوند.</p>' WHERE slug='guide-13-brake-vibration';
UPDATE articles SET title_fa='چراغ ABS روشن شده است؛ رانندگی کنیم یا نه؟', content_fa='<h2>ایمنی</h2><p>ترمز معمولی ممکن است فعال بماند اما عملکرد ضدقفل تضمین نیست؛ ادامه رانندگی با احتیاط و مراجعه سریع ضروری است.</p><h2>تشخیص</h2><p>خطای ABS و سنسورهای چرخ باید با دستگاه تخصصی بررسی شوند.</p>' WHERE slug='guide-14-abs-light';
UPDATE articles SET title_fa='ریست سرویس و کدینگ ECU چه تفاوتی دارند؟', content_fa='<h2>تفاوت دو عملیات</h2><p>ریست سرویس یک عملیات نگهداری است، اما کدینگ تنظیمات ماژول را تغییر می‌دهد.</p><h2>پیش‌نیاز</h2><p>کدینگ به ولتاژ پایدار، شماره قطعه صحیح و سازگاری نرم‌افزار نیاز دارد.</p>' WHERE slug='guide-15-ecu-coding';
UPDATE articles SET title_fa='مصرف سوخت بالا در شهر؛ پنج بررسی قبل از تعویض قطعه', content_fa='<h2>بررسی‌های اولیه</h2><p>فشار باد، گیرکردن ترمز، دمای موتور، اصلاح سوخت و نشتی هوا پیش از هزینه برای قطعات بررسی می‌شوند.</p><h2>داده ECU</h2><p>داده زنده و اصلاح سوخت مسیر تشخیص را دقیق‌تر می‌کند.</p>' WHERE slug='guide-16-fuel-consumption';
UPDATE articles SET title_fa='داغ کردن موتور؛ اقدام فوری و علت‌های اصلی', content_fa='<h2>اقدام فوری</h2><p>ادامه رانندگی با دمای بالا ریسک آسیب سرسیلندر دارد؛ خودرو را متوقف و اجازه دهید سیستم خنک شود.</p><h2>علت‌ها</h2><p>سطح مایع، فن، ترموستات، رادیاتور و نشتی باید بررسی شوند.</p>' WHERE slug='guide-17-overheating';
UPDATE articles SET title_fa='چه زمانی شمع و کوئل نیاز به بررسی دارند؟', content_fa='<h2>علائم</h2><p>ریپ زدن زیر بار، سخت روشن شدن و خطای میس‌فایر از نشانه‌های مهم هستند.</p><h2>تشخیص</h2><p>تست جرقه و مقایسه عملکرد سیلندرها قبل از تعویض کوئل انجام می‌شود.</p>' WHERE slug='guide-18-spark-coil';
UPDATE articles SET title_fa='نگهداری خودروهای چینی با سیستم‌های الکترونیکی پیچیده', content_fa='<h2>نکات مهم</h2><p>ثبت خطاهای متناوب، سلامت باتری و به‌روزرسانی نرم‌افزار برای جلوگیری از خرابی‌های زنجیره‌ای اهمیت دارد.</p><h2>دیاگ</h2><p>اسکن همه ماژول‌ها و بررسی شبکه ارتباطی باید بخشی از عیب‌یابی باشد.</p>' WHERE slug='guide-19-chinese-car-electronics';
UPDATE articles SET title_fa='سرویس دوره‌ای خودروهای توربو؛ روغن، دما و رانندگی درست', content_fa='<h2>نگهداری توربو</h2><p>روغن با مشخصات صحیح، گرم و سرد کردن منطقی و بررسی شیلنگ‌های هوای ورودی عمر توربو را بیشتر می‌کند.</p><h2>بازدید</h2><p>نشتی روغن و هوا و سلامت سیستم خنک‌کاری باید در سرویس‌های دوره‌ای بررسی شوند.</p>' WHERE slug='guide-20-turbo-maintenance';
